PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS clinics (id TEXT PRIMARY KEY, name TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, clinic_id TEXT NOT NULL REFERENCES clinics(id), email TEXT NOT NULL UNIQUE, name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','physician','assistant','auditor')), password_hash TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), csrf TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS patients (id TEXT PRIMARY KEY, clinic_id TEXT NOT NULL REFERENCES clinics(id), mrn TEXT NOT NULL, name TEXT NOT NULL, age INTEGER NOT NULL, sex TEXT NOT NULL, color TEXT NOT NULL, allergies TEXT NOT NULL DEFAULT 'Not documented', medications TEXT NOT NULL DEFAULT 'Not documented', history TEXT NOT NULL DEFAULT 'Not documented', version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, UNIQUE(clinic_id,mrn));
CREATE TABLE IF NOT EXISTS encounters (id TEXT PRIMARY KEY, clinic_id TEXT NOT NULL REFERENCES clinics(id), patient_id TEXT NOT NULL REFERENCES patients(id), reason TEXT NOT NULL, date TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Draft', note TEXT NOT NULL DEFAULT '', version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS procedures (id TEXT PRIMARY KEY, encounter_id TEXT NOT NULL REFERENCES encounters(id), clinic_id TEXT NOT NULL REFERENCES clinics(id), type TEXT NOT NULL, site TEXT NOT NULL, phase TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS media (id TEXT PRIMARY KEY, clinic_id TEXT NOT NULL REFERENCES clinics(id), patient_id TEXT NOT NULL REFERENCES patients(id), encounter_id TEXT NOT NULL REFERENCES encounters(id), procedure_id TEXT, name TEXT NOT NULL, mime TEXT NOT NULL, bytes INTEGER NOT NULL, sha256 TEXT NOT NULL, file_key TEXT NOT NULL UNIQUE, site TEXT NOT NULL, phase TEXT NOT NULL, source TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('pending_review','committed')), parent_id TEXT REFERENCES media(id), manifest TEXT, created_at TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES users(id), committed_at TEXT);
CREATE TABLE IF NOT EXISTS audit_events (id TEXT PRIMARY KEY, clinic_id TEXT NOT NULL REFERENCES clinics(id), actor_id TEXT NOT NULL REFERENCES users(id), action TEXT NOT NULL, target_id TEXT NOT NULL, event_time TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS patients_clinic ON patients(clinic_id);
CREATE INDEX IF NOT EXISTS encounters_patient ON encounters(clinic_id,patient_id);
CREATE INDEX IF NOT EXISTS media_patient ON media(clinic_id,patient_id,state);
